#!/usr/bin/env bash
# Imports the OTel SDK traces health dashboard (PR #266) into a local Kibana.
# Creates a data view that maps serverless.metrics-* -> metrics-* so the
# dashboard panels resolve against local APM Server data.
set -euo pipefail

KIBANA_URL="${KIBANA_URL:-http://localhost:5601}"
ES_USER="${ES_USER:-elastic-admin}"
ES_PASS="${ES_PASS:-elastic-password}"

auth="${ES_USER}:${ES_PASS}"

wait_for_kibana() {
  echo "Waiting for Kibana at ${KIBANA_URL}..."
  local start; start=$(date +%s)
  until curl -sf -u "${auth}" "${KIBANA_URL}/api/status" | grep -q '"level":"available"' 2>/dev/null; do
    if [ $(( $(date +%s) - start )) -ge 300 ]; then
      echo "ERROR: Kibana did not become available within 5 minutes." >&2
      exit 1
    fi
    sleep 5
  done
  echo "Kibana is ready."
}

create_data_view() {
  echo "Creating data view 'serverless.metrics-*' -> 'metrics-*'..."
  # Use the serverless.metrics-* ID so the dashboard panels resolve it locally.
  local response
  response=$(curl -sf -u "${auth}" \
    -X POST "${KIBANA_URL}/api/data_views/data_view" \
    -H "kbn-xsrf: true" \
    -H "Content-Type: application/json" \
    -d '{
      "data_view": {
        "id": "serverless.metrics-*",
        "title": "metrics-*",
        "timeFieldName": "@timestamp"
      }
    }' 2>&1) || true
  echo "  $response"
  echo "Done."
}

import_dashboard() {
  echo "Importing OTel SDK traces health dashboard..."
  local tmpfile; tmpfile=$(mktemp /tmp/otel-dashboard-XXXX.ndjson)
  # Dashboard saved object from elasticsearch-o11y-resources PR #266.
  # References serverless.metrics-* index pattern (created above).
  # Navigation links panels will show as missing locally — the metric charts still work.
  cat > "${tmpfile}" << 'NDJSON'
